"""Independent rubric evaluator for saved Earhart Hall candidate."""
from pathlib import Path
import json

def evaluate(fresh_open_path, footprint_path):
    fresh = json.loads(Path(fresh_open_path).read_text(encoding="utf-8"))
    fp = json.loads(Path(footprint_path).read_text(encoding="utf-8"))
    criteria = [
        {"name":"Correct identity and source-backed footprint","score":2,"max_score":2,"evidence":"Fresh-opened expected Earhart asset ID; matched Purdue BuildingShapes feature 61 (ERHT, Amelia Earhart Residence Hall, 1275 1st Street). Independent comparison: 38 model floor-ring vertices versus the raw 109-coordinate closed GIS ring; model vertices deviate <=0.00004 m from the GIS polyline and source vertices deviate <=0.625 m from the simplified model polyline."},
        {"name":"Position, orientation, and scale/dimensions","score":2,"max_score":2,"evidence":"Campus-coordinate bounds of the saved floor ring match the GIS-converted bounds within ~0.00003 m. Footprint shape directly agrees with the GIS edge order/rotation; dimensions are approximately 86.14 x 70.55 m. The projection is the project's local geographic approximation, not a surveyed CRS."},
        {"name":"Evidence-backed height, floors, and roof form","score":1,"max_score":2,"evidence":"Eight modeled levels are consistent with Purdue move-in directions (floors 6-8) and the contractor's renovation scope (floors 1-8); the exterior photograph and render support a low flat roof. The model's 24.75 m roof height and exact floor elevations remain estimates; GIS NUM_LEVELS/CountOfFLO=10 conflicts with eight modeled floors and field units/semantics do not resolve the discrepancy."},
        {"name":"Facade, entrances, and distinctive architecture","score":1,"max_score":2,"evidence":"The fresh render shows a large brick residence-hall mass, repetitive window rhythm, pale trim, dining-court recess/storefront, canopy, steps, and signage components. Compared with the saved current entrance photograph, the model omits the prominent Earhart statue/pedestal and readable dining-court sign; brick appears strongly striped and the entry/plaza treatment is simplified. A single close source photo and an oblique render limit judgment of the entire facade."},
        {"name":"Modular export, portability, and complete evidence","score":2,"max_score":2,"evidence":"Exact candidate re-opened in Blender 5.2.3 as scene Building_massing_earhart_hall_0f14209 with expected Asset_massing_earhart_hall_0f14209 collection and 25 objects. No non-packed external image dependencies. Builder evidence includes GIS snapshot/metadata, official room-layout illustration, source photos, evidence note, geometry/build report and previews; independent fresh-open and GIS comparison records are saved with this result. Root manifest's cached object_count/name/bounds still describes the prior one-object 16 m massing, so coordinator should refresh that shared index when integrating."}
    ]
    score=sum(c["score"] for c in criteria)
    findings=[
       {"priority":"recommended","finding":"Add the documented statue and pedestal at the dining entrance and make the 'Earhart Dining Court' header legible; use the entrance reference photograph for their position and scale."},
       {"priority":"recommended","finding":"Tune the procedural brick so broad orange-red brick bays read as masonry rather than narrow vertical striping; retain the broad light-colored vertical pilasters and check them against source photography."},
       {"priority":"coordinator integration","finding":"Refresh modular/manifest.json metadata for this same asset path (object list/count and bounds); the current cached manifest row still reports one object and a 16 m height while the candidate contains 25 objects and reaches 25.49 m."},
       {"priority":"uncertainty","finding":"Obtain a source with measured elevations/roof height or document the GIS floor/roof field units. Current eight-story count is supported, while 24.75 m roof height and modeled story intervals are estimates."},
       {"priority":"interior evidence","finding":"The file contains representative 2-person room floors, partitions, furniture and bedding plus dining furniture, but the evidence package does not include an independently viewable interior render; save a cutaway/interior preview on the next iteration."}
    ]
    return {"building_id":"massing_earhart_hall_0f14209","candidate_sha256":fresh["sha256"],"score":score,"max_score":10,"status":"PASS" if score>=8 else "FAIL","pass_threshold":8,"criteria":criteria,"evidence":{"fresh_open":fresh,"gis_footprint_comparison":fp,"review_renders":["fresh_open_overview.png","isolated_room_plan.png"],"reviewed_builder_renders":["../earhart_hall/exterior_preview.png","../earhart_hall/dining_court_entry_preview.png"],"sources":[{"url":"https://services.arcgis.com/uCvss3umN5nvK9wW/arcgis/rest/services/BuildingShapes/FeatureServer/0","provider":"Purdue University GIS","feature_id":61,"retrieval_date":"2026-10-26","crs":"EPSG:4326"},{"url":"https://www.housing.purdue.edu/my-housing/options/residence-halls/earhart.html","provider":"Purdue University Residences","retrieval_date":"2026-10-26"},{"url":"https://housing.purdue.edu/move-in/west-lafayette/move-in/directions/earhart.html","provider":"Purdue University Residences","retrieval_date":"2026-10-26"},{"url":"https://aecme.com/project/purdue-university-earhart-residential-renovation/","provider":"AECME project description","retrieval_date":"2026-10-26"},{"url":"https://pinolaphoto.com/2026/10/12/designed-by-scholer-earhart-hall/","provider":"Dave Wegiel / Pinola Photo","source_date":"2026-10-12"}]},"findings":findings}
